from greeting import greet


class GreetTest(unittest.TestCase):
    def test_greets_name_with_non_ascii_characters(self):
        self.assertEqual(greet("Siobhán Ní Dhúill"), "Hello, Siobhán Ní Dhúill!")


if __name__ == "__main__":
    unittest.main()

